    50	function validationMessage(errors: ErrorObject[]): string {
    51	  const error = errors[0];
    52	  if (!error) return 'Input failed schema validation';
    53	
    54	  const details = error as ErrorObject & {instancePath?: string; dataPath?: string};
    55	  const params = details.params as Record<string, unknown>;
    56	  const missingProperty = params.missingProperty;
    57	  const schemaPath = details.schemaPath.replace(/^#/, '');
    58	  const propertiesPath = schemaPath.replace(/\/properties\/([^/]+)/g, '/$1');
    59	  const propertyPathFromSchema = propertiesPath.replace(/\/(?:required|type|enum)$/, '') || '/';
    60	  const instancePath = details.instancePath ?? details.dataPath;
    61	  const path = instancePath ? normalizeInstancePath(instancePath) : propertyPathFromSchema;
    62	  const hasMissingProperty = details.keyword === 'required' && typeof missingProperty === 'string';
    63	  const propertyPath = hasMissingProperty
    64	    ? path === '/'
    65	      ? `/${missingProperty}`
    66	      : `${path}/${missingProperty}`
    67	    : path;
    68	  if (details.keyword === 'required') return `Input validation failed at ${propertyPath}: property is required`;
    69	  if (details.keyword === 'type') return `Input validation failed at ${path}: must be ${String(params.type)}`;
    70	  if (details.keyword === 'enum') return `Input validation failed at ${path}: value must match the enum constraint`;
    71	  return `Input validation failed at ${path}: ${details.message ?? 'schema constraint failed'}`;
    72	}
    73	
    74	function normalizeInstancePath(path: string): string {
    75	  if (path.startsWith('/')) return path;
    76	  if (!path.startsWith('.')) return path || '/';
    77	  const segments = path.slice(1).split('.');
    78	  const escapedSegments = segments.map(escapeJsonPointerSegment);
    79	  const pointerSegments = escapedSegments.map(segment => `/${segment}`);
    80	  return pointerSegments.join('') || '/';
    81	}
    82	
    83	function escapeJsonPointerSegment(segment: string): string {
    84	  const withoutTilde = segment.replace(/~/g, '~0');
    85	  return withoutTilde.replace(/\//g, '~1');
    86	}
